declare(strict_types=1);
if(file_exists(__DIR__.'/../.git'))throw new RuntimeException('Isolated copy required');
require __DIR__.'/../src/Core/Autoloader.php';
use Berserk\Core\{Autoloader,GameState,CardInstance,Engine,Command,Result,CardHealing,DamageResolver,TurnPhaseProcessor,WoundTransferProcessor};
use Berserk\Core\BattleHistory\{Recorder,JournalText};
Autoloader::register();Autoloader::addNamespace('Berserk\\',__DIR__.'/../src/');
$defs=[];foreach(json_decode(ltrim(file_get_contents(__DIR__.'/health-s1-fixture.json'),"\xEF\xBB\xBF"),true,512,JSON_THROW_ON_ERROR)as$d)$defs[$d['ukid']]=$d;
function hc(bool $ok,string $m):void{if(!$ok)throw new RuntimeException($m);}
function card(int$id,string$ukid,string$owner,int$row,int$col):CardInstance{global$defs;$d=$defs[$ukid];return new CardInstance(instanceId:$id,ukid:$ukid,owner:$owner,zone:'field',row:$row,col:$col,hp:(int)$d['health'],hpMax:(int)$d['health'],prop:json_decode($d['prop']??'{}',true)?:[],move:2,moveMax:2,strikeWeak:1,strikeMedium:2,strikeStrong:3);}
function seed():GameState{$s=new GameState(81,1,2);$s->status='battle';$s->battle=['turn'=>1,'active'=>'host','strike'=>null];$s->addCard(card(1,'s1_71','host',3,1));$s->addCard(card(2,'s1_128','host',3,2));$s->addCard(card(3,'s1_1','player',4,2));return$s;}
$checks=[];
function pair(string$name,GameState$seed,Closure$run,Closure$verify):void{global$defs,$checks;$a=GameState::fromArray($seed->toArray());$b=GameState::fromArray($seed->toArray());$r=new Recorder(81,1,[],[],true,fn($c)=>$defs[$c->ukid]['name']);$b->historyRecorder=$r;$r->commandStarted($b,'host',new Command('fixture'));$x=$run($a);$y=$run($b);hc($a->toArray()===$b->toArray(),$name.' DTO mismatch');hc(serialize($x)===serialize($y),$name.' result mismatch');$r->commandFinished($b,Result::ok());$events=$r->batch($b)->data()['events'];$verify($events,$b);$checks[]=$name;}
function events(array$es,string$type):array{return array_values(array_filter($es,fn($e)=>$e['type']===$type));}
foreach([1,3,99]as$amount){$s=seed();$s->cards[2]->hp-=3;pair('heal cap '.$amount,$s,fn($s)=>(new CardHealing($s,new Engine()))->begin($s->cards[1],$s->cards[2],$amount,'heal'),function($es)use($amount){$e=events($es,'card.healed');hc(count($e)===1&&$e[0]['payload']['amount']===min(3,$amount),'single actual heal');});}
$s=seed();$s->cards[2]->hp-=3;$s->cards[1]->revealed=false;pair('hidden healer visible target',$s,fn($s)=>(new CardHealing($s,new Engine()))->begin($s->cards[1],$s->cards[2],2,'secret'),function($es){$e=events($es,'card.healed')[0];hc($e['player']!==null,'public outcome lost');hc(!str_contains(json_encode($e['player']),'Леший')&&!isset($e['player']['source_id']),'hidden source leak');});
$s=seed();$s->cards[2]->hp-=3;pair('regeneration',$s,function($s){return(new ReflectionMethod(TurnPhaseProcessor::class,'executeRegen'))->invoke(new TurnPhaseProcessor($s,new Engine()),'host');},function($es){$e=events($es,'card.healed');hc(count($e)===1&&$e[0]['payload']['ability']==='regeneration','regen');});
foreach([1,4]as$armor){$s=seed();$s->cards[2]->armor=$armor;pair('armor '.$armor,$s,fn($s)=>(new DamageResolver($s))->applyDamage($s->cards[2],3,'shot',$s->cards[3]),function($es)use($armor){hc(count(events($es,'health.armor'))===1,'one armor');$e=events($es,'health.armor')[0];hc($e['payload']['amount']===min(3,$armor),'actual armor');hc(count(events($es,'combat.wounds'))===1,'single wounds');hc(array_search('health.armor',array_column($es,'type'))<array_search('combat.wounds',array_column($es,'type')),'armor before wounds');});}
foreach(['answer','shield']as$kind){$s=seed();if($kind==='answer')$s->cards[2]->prop['block_strike_answer']=true;else$s->cards[2]->modifiers[]=['stat'=>'shield_light','value'=>1];pair('prevent '.$kind,$s,fn($s)=>(new DamageResolver($s))->applyDamage($s->cards[2],3,$kind==='answer'?'answer':'shot',$s->cards[3]),function($es){hc(count(events($es,'health.prevented'))===1&&!events($es,'combat.wounds'),'actual prevention only');});}
foreach([false,true]as$queued){$s=seed();$s->cards[1]=card(1,'s1_179','host',3,1);$s->cards[1]->hp=1;if($queued)$s->battle['strike']=['deadeat_queue'=>[['instance_id'=>1]]];pair('deadeat '.(int)$queued,$s,function($s)use($queued){$d=new DamageResolver($s);if($queued)$d->flushDeadeatQueue();else$d->forceDeath($s->cards[3],'strike',$s->cards[1]);},function($es)use($queued){hc(count(events($es,'health.maximum'))===1&&count(events($es,'card.healed'))===1,'deadeat actual facts');hc(count(events($es,'combat.death'))===($queued?0:1),'no death duplicate');hc(array_search('health.maximum',array_column($es,'type'))<array_search('card.healed',array_column($es,'type')),'maximum before restore');});}
$s=seed();$s->cards[2]=card(2,'s1_83','host',3,2);$s->cards[2]->closed=true;pair('heal opens Serk',$s,fn($s)=>(new CardHealing($s,new Engine()))->begin($s->cards[1],$s->cards[2],2,'heal',[],['active'=>true,'allow_open'=>true]),function($es){hc(!events($es,'card.healed')&&count(events($es,'health.replaced'))===1,'no imaginary heal');});
foreach(['s1_3','s1_109','s1_110','s1_184']as$ukid){$s=seed();$s->cards[1]=card(1,$ukid,'host',3,1);$s->cards[2]->hp-=2;$s->battle['pending_wound_transfer']=['owner'=>'host','source_id'=>1,'donor_id'=>2,'transfers'=>[['target_id'=>3,'amount'=>2]],'options'=>['on_finish'=>'main_phase']];pair('transfer '.$ukid,$s,fn($s)=>(new WoundTransferProcessor($s,new Engine()))->finish('host'),function($es){hc(count(events($es,'health.transfer_out'))===1,'donor fact');hc(count(events($es,'combat.wounds'))===1,'recipient no double wounds');hc(!events($es,'card.healed'),'no false card heal');});}
$s=seed();$s->cards[2]=card(2,'s1_81','host',3,2);
pair('satyr replacement actual pending',$s,function($s){$h=new CardHealing($s,new Engine());$r=$h->begin($s->cards[1],$s->cards[2],2,'heal');hc($r===null,'satyr must wait');$token=$s->battle['pending_heal_instead_wound']['token'];$a=$h->chooseSatyr('host',new Command('choose_heal_instead_wound',['heal_token'=>$token,'target_id'=>3]));$before=$s->toArray();$retry=$h->chooseSatyr('host',new Command('choose_heal_instead_wound',['heal_token'=>$token,'target_id'=>3]));hc(!$retry->success&&$before===$s->toArray(),'stale replacement must do nothing');return $a;},function($es){hc(!events($es,'card.healed'),'replacement is not healing');hc(count(events($es,'combat.wounds'))===1&&count(events($es,'health.replaced'))===1,'replacement consequence exactly once');hc(array_search('combat.wounds',array_column($es,'type'))<array_search('health.replaced',array_column($es,'type')),'actual wounds before replacement summary');});
$s=seed();$s->cards[1]=card(1,'s1_154','host',3,1);$s->cards[1]->hp=9;$s->cards[3]->hp-=2;
pair('noble blocks healing after pending',$s,function($s){$h=new CardHealing($s,new Engine());hc($h->begin($s->cards[2],$s->cards[3],2,'heal')===null,'noble pending');return $h->choose('host',new Command('choose_card_heal',['heal_token'=>$s->battle['pending_card_heal']['token'],'apply'=>'yes']));},function($es){hc(!events($es,'card.healed')&&count(events($es,'health.replaced'))===1,'blocked heal not successful');});
$s=seed();pair('full HP no fictitious heal',$s,fn($s)=>(new CardHealing($s,new Engine()))->begin($s->cards[1],$s->cards[2],3,'heal'),function($es){hc(!events($es,'card.healed')&&!events($es,'health.replaced'),'full no-op');});
$s=seed();$s->cards[2]->hp-=3;pair('explicit full healing',$s,fn($s)=>(new CardHealing($s,new Engine()))->begin($s->cards[1],$s->cards[2],99,'heal',[],['active'=>true,'full'=>true]),function($es){$e=events($es,'card.healed');hc(count($e)===1&&$e[0]['payload']['amount']===3,'full actual amount');});
$s=seed();$s->cards[1]->revealed=false;pair('hidden source wounds remain public',$s,fn($s)=>(new DamageResolver($s))->applyDamage($s->cards[3],1,'shot',$s->cards[1]),function($es){$e=events($es,'combat.wounds')[0];hc($e['player']!==null&&!isset($e['player']['source_id']),'hidden source wounds projection');hc(!str_contains(json_encode($e['player']),'Леший'),'hidden name');});
$s=seed();$s->cards[2]->hp-=2;$s->cards[3]->revealed=false;$s->battle['pending_wound_transfer']=['owner'=>'host','source_id'=>1,'donor_id'=>2,'transfers'=>[['target_id'=>3,'amount'=>2]],'options'=>['on_finish'=>'main_phase']];
pair('hidden transfer recipient projection',$s,fn($s)=>(new WoundTransferProcessor($s,new Engine()))->finish('host'),function($es){$e=events($es,'health.transfer_out')[0];hc($e['host']['recipients']===[]&&!isset($e['host']['recipient_ids']),'hidden recipient leaked');hc($e['player']['recipients']===['Кочевник'],'known recipient missing');});
echo json_encode(['status'=>'PASS','checks'=>$checks],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT)."\n";
